import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.jwovEGr5.js";const g=JSON.parse('{"title":"SLSA Build Attestation","description":"","frontmatter":{},"headers":[],"relativePath":"slsa.md","filePath":"slsa.md"}'),r={name:"slsa.md"};function o(n,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="slsa-build-attestation" tabindex="-1">SLSA Build Attestation <a class="header-anchor" href="#slsa-build-attestation" aria-label="Permalink to &quot;SLSA Build Attestation&quot;">​</a></h1><p>This repository publishes build provenance for release artifacts in accordance with <a href="https://slsa.dev" target="_blank" rel="noreferrer">SLSA (Supply-chain Levels for Software Artifacts)</a> Build specifications. SLSA provenance allows downstream consumers to verify that an artifact was built from the expected source repository, at the expected commit, by the expected build platform.</p><h2 id="target-level" tabindex="-1">Target Level <a class="header-anchor" href="#target-level" aria-label="Permalink to &quot;Target Level&quot;">​</a></h2><p><strong>Current target: SLSA Build L2 (achieved today)</strong></p><p>The release pipeline is hosted on GitHub Actions, an isolated build platform that is owned and administered by GitHub. Provenance is generated automatically for every published release using <a href="https://github.com/slsa-framework/slsa-github-generator" target="_blank" rel="noreferrer"><code>slsa-framework/slsa-github-generator</code></a> and the <code>attest-build-provenance</code> action. Provenance is signed by a GitHub- hosted OIDC token and stored in the <a href="https://docs.github.com/en/security/supply-chain-security/artifact-attestations" target="_blank" rel="noreferrer">GitHub Artifact Attestations</a> log alongside the artifact.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Status</th></tr></thead><tbody><tr><td>Provenance generated automatically</td><td>✅ L2</td></tr><tr><td>Provenance distributed alongside artifact</td><td>✅ L2</td></tr><tr><td>Build platform hosted and isolated</td><td>✅ L2</td></tr><tr><td>Provenance authenticity (OIDC-signed)</td><td>✅ L2</td></tr><tr><td><code>SOURCE_DATE_EPOCH</code> seeded on release build</td><td>✅ seeded</td></tr><tr><td>Bit-identical repro-check (local + CI)</td><td>✅ L52 gate</td></tr><tr><td>Build platform isolated from build request</td><td>⏭ L3 target</td></tr><tr><td>Hardened build platform</td><td>⏭ L3 target</td></tr><tr><td>Provenance non-forgeable (sigstore/cosign)</td><td>⏭ L3 target</td></tr></tbody></table><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>The CI workflow lives at <a href="../.github/workflows/release-attestation.yml"><code>.github/workflows/release-attestation.yml</code></a> and is triggered:</p><ul><li>Automatically on every <code>release: published</code> event.</li><li>Manually via <code>workflow_dispatch</code> for ad-hoc provenance generation.</li></ul><h3 id="build-steps" tabindex="-1">Build Steps <a class="header-anchor" href="#build-steps" aria-label="Permalink to &quot;Build Steps&quot;">​</a></h3><ol><li><strong>Checkout</strong> — full history (<code>fetch-depth: 0</code>) so the git revision can be embedded in provenance.</li><li><strong>Toolchain</strong> — pinned <code>stable</code> Rust via <a href="https://github.com/dtolnay/rust-toolchain" target="_blank" rel="noreferrer"><code>dtolnay/rust-toolchain</code></a>.</li><li><strong>Cache</strong> — cargo registry, git index, and <code>target/</code> via <a href="https://github.com/Swatinem/rust-cache" target="_blank" rel="noreferrer"><code>Swatinem/rust-cache</code></a>.</li><li><strong>Build</strong> — <code>cargo build --release --locked --workspace --all-targets</code>.</li><li><strong>Stage</strong> — collect built executables, source tarball, and a build manifest into <code>release-artifacts/</code>.</li><li><strong>Upload</strong> — publish <code>release-artifacts</code> as a GitHub Actions artifact (90 day retention).</li><li><strong>Attest</strong> — generate SLSA Build L2 provenance with <code>slsa-framework/slsa-github-generator/attest-build-provenance@v1</code>.</li></ol><h2 id="reproducible-builds-l52" tabindex="-1">Reproducible builds (L52) <a class="header-anchor" href="#reproducible-builds-l52" aria-label="Permalink to &quot;Reproducible builds (L52)&quot;">​</a></h2><p>Release binaries are built with <code>SOURCE_DATE_EPOCH=0</code> (see <a href="../.github/workflows/release.yml"><code>.github/workflows/release.yml</code></a> and <a href="https://github.com/KooshaPari/sharecli/blob/main/scripts/repro-check.sh" target="_blank" rel="noreferrer"><code>scripts/repro-check.sh</code></a>).</p><table tabindex="0"><thead><tr><th>Surface</th><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td>Local (unix)</td><td><code>just repro-check</code></td><td>Builds twice into isolated <code>CARGO_TARGET_DIR</code>s; compares SHA-256</td></tr><tr><td>CI</td><td><a href="../.github/workflows/repro-check.yml"><code>.github/workflows/repro-check.yml</code></a></td><td><code>ubuntu-latest</code> on lockfile / source changes</td></tr><tr><td>Release matrix</td><td><code>release.yml</code> <code>build</code> job</td><td>Cross-target tarballs; per-target repro not yet gated</td></tr></tbody></table><p>On Windows hosts the script exits 0 with a skip message — reproducibility is enforced on unix CI only (spawn-core-sys uses a Rust stub on Windows).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optional: pin epoch explicitly (default 0)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SOURCE_DATE_EPOCH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repro-check</span></span></code></pre></div><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Consumers can verify a release artifact&#39;s provenance using the <a href="https://cli.github.com" target="_blank" rel="noreferrer">GitHub CLI</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attestation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">artifac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --owner</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">or</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Or with <a href="https://github.com/sigstore/cosign" target="_blank" rel="noreferrer"><code>cosign</code></a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify-attestation</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-identity-regexp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://github.com/slsa-framework/slsa-github-generator&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-oidc-issuer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://token.actions.githubusercontent.com&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">artifac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The in-toto provenance attestation (<code>slsa-github-generator/actions/attest-build-provenance</code>) contains:</p><ul><li><code>builder.id</code> — <code>https://github.com/actions/runner</code></li><li><code>invocation.config.source.uri</code> — repository URL</li><li><code>invocation.config.source.entryPoint</code> — build workflow path</li><li><code>invocation.config.source.digest.sha1</code> — git commit SHA</li><li><code>invocation.config.source.ref</code> — git ref (tag / branch)</li><li><code>metadata.buildInvocationID</code> — workflow run ID</li><li><code>metadata.completeness.parameters</code> — whether all inputs are hashed</li><li><code>metadata.completeness.environment</code> — whether environment is fully captured</li></ul><h2 id="path-to-slsa-build-l3" tabindex="-1">Path to SLSA Build L3 <a class="header-anchor" href="#path-to-slsa-build-l3" aria-label="Permalink to &quot;Path to SLSA Build L3&quot;">​</a></h2><p>The current pipeline satisfies L2. To graduate to L3, the following additions are required:</p><ol><li><strong>Isolated build environment</strong> — move from a hosted runner to ephemeral, single-tenant builders (e.g. <code>slsa-framework/slsa-github-generator</code>&#39;s <code>generator_containerized_slsa3.yml</code> reusable workflow, or a self-hosted runner with a hardened image).</li><li><strong>Provenance non-forgeability</strong> — the generator workflow re-signs provenance with a build-platform-held signing key (sigstore / KMS) rather than relying on the GitHub OIDC token alone.</li><li><strong>Provenance transparency log</strong> — the generator publishes provenance to a transparency log (e.g. Rekor) so forgery is detectable by the wider community.</li></ol><p>To upgrade, switch the <code>attest-build-provenance</code> step to invoke the <code>slsa-framework/slsa-github-generator/.github/workflows/generator_containerized_slsa3.yml@v2</code> reusable workflow with a build image pinned by digest. The reusable workflow handles ephemeral runners, hardened isolation, and non-forgeable provenance signing transparently.</p><h2 id="container-image-provenance-l56-roadmap" tabindex="-1">Container image provenance (L56 roadmap) <a class="header-anchor" href="#container-image-provenance-l56-roadmap" aria-label="Permalink to &quot;Container image provenance (L56 roadmap)&quot;">​</a></h2><p><code>Containerfile</code> builds a local/podman image today; <strong>GHCR publish is not wired yet</strong>. When image publish lands, the planned cosign path (no secrets required in this doc) is:</p><ol><li><strong>Build</strong> — multi-stage <code>Containerfile</code> on <code>ubuntu-latest</code> (digest-pinned base images).</li><li><strong>Sign</strong> — <code>cosign sign --yes ghcr.io/&lt;org&gt;/sharecli:&lt;tag&gt;</code> with GitHub OIDC (<code>id-token: write</code> + <code>packages: write</code>).</li><li><strong>Attest</strong> — <code>cosign attest --type slsaprovenance --predicate …</code> or GitHub Artifact Attestations for the OCI digest.</li><li><strong>Verify (consumers)</strong> — before deploy:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cosign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">or</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/sharecli:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-identity-regexp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://github.com/KooshaPari/sharecli/.*&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --certificate-oidc-issuer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://token.actions.githubusercontent.com&#39;</span></span></code></pre></div><p>Until GHCR publish exists, use <code>podman build -f Containerfile</code> locally and Trivy scan via <code>.github/workflows/security.yml</code> when a root <code>Dockerfile</code> is added. Signing remains <strong>documented-only</strong> — no cosign secrets in CI yet.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://slsa.dev" target="_blank" rel="noreferrer">SLSA Framework</a></li><li><a href="https://github.com/slsa-framework/slsa-github-generator" target="_blank" rel="noreferrer"><code>slsa-framework/slsa-github-generator</code></a></li><li><a href="https://docs.github.com/en/security/supply-chain-security/artifact-attestations" target="_blank" rel="noreferrer">GitHub Artifact Attestations</a></li><li><a href="https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions" target="_blank" rel="noreferrer">GitHub Actions security hardening</a></li><li><a href="https://github.com/dtolnay/rust-toolchain" target="_blank" rel="noreferrer"><code>dtolnay/rust-toolchain</code></a></li><li><a href="https://github.com/Swatinem/rust-cache" target="_blank" rel="noreferrer"><code>Swatinem/rust-cache</code></a></li><li><a href="https://github.com/sigstore/cosign" target="_blank" rel="noreferrer"><code>cosign</code></a></li></ul>`,34)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
